import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int servers = nextInt(), n = nextInt();
        PriorityQueue<Integer> idle = new PriorityQueue<>();
        for (int i = 0; i < servers; i++) idle.add(i);
        // busy holds {end time, server id}.
        PriorityQueue<long[]> busy = new PriorityQueue<>((x, y) -> x[0] != y[0] ? Long.compare(x[0], y[0]) : Long.compare(x[1], y[1]));
        long now = 0;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            long length = nextLong();
            now = Math.max(now, i);
            if (idle.isEmpty()) now = Math.max(now, busy.peek()[0]);
            while (!busy.isEmpty() && busy.peek()[0] <= now) idle.add((int) busy.poll()[1]);
            int server = idle.poll();
            if (i > 0) sb.append(' ');
            sb.append(server);
            busy.add(new long[] {now + length, server});
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"container/heap"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

type intHeap []int

func (h intHeap) Len() int           { return len(h) }
func (h intHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h intHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *intHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *intHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

// job is a busy server: its release time and id.
type job struct{ end, server int }

type jobHeap []job

func (h jobHeap) Len() int { return len(h) }
func (h jobHeap) Less(i, j int) bool {
	if h[i].end != h[j].end {
		return h[i].end < h[j].end
	}
	return h[i].server < h[j].server
}
func (h jobHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
func (h *jobHeap) Push(x any)   { *h = append(*h, x.(job)) }
func (h *jobHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	servers, n := nextInt(), nextInt()
	idle := &intHeap{}
	for i := 0; i < servers; i++ {
		*idle = append(*idle, i)
	}
	busy := &jobHeap{}
	now := 0
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	for i := 0; i < n; i++ {
		length := nextInt()
		now = max(now, i)
		if idle.Len() == 0 {
			now = max(now, (*busy)[0].end)
		}
		for busy.Len() > 0 && (*busy)[0].end <= now {
			heap.Push(idle, heap.Pop(busy).(job).server)
		}
		server := heap.Pop(idle).(int)
		if i > 0 {
			out.WriteByte(' ')
		}
		out.WriteString(strconv.Itoa(server))
		heap.Push(busy, job{now + length, server})
	}
	out.WriteByte('\n')
}
